	@Test
	void correlatedOptionalRightJoinRetainsOuterBindingsInsteadOfHashingGlobalInputs(@TempDir Path dataDirectory) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(0L);
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (var connection = repository.getConnection()) {
				var values = connection.getValueFactory();
				IRI type = values.createIRI("urn:frontier:type");
				IRI patient = values.createIRI("urn:frontier:Patient");
				IRI hasEncounter = values.createIRI("urn:frontier:hasEncounter");
				IRI hasCondition = values.createIRI("urn:frontier:hasCondition");
				connection.begin();
				for (int index = 0; index < 300; index++) {
					IRI root = values.createIRI("urn:frontier:root:" + index);
					connection.add(root, type, patient);
					for (int encounterOrdinal = 0; encounterOrdinal < 2; encounterOrdinal++) {
						IRI encounter = values.createIRI(
								"urn:frontier:encounter:" + index + ':' + encounterOrdinal);
						connection.add(root, hasEncounter, encounter);
						for (int conditionOrdinal = 0; conditionOrdinal < 2; conditionOrdinal++) {
							connection.add(encounter, hasCondition, values.createIRI(
									"urn:frontier:condition:" + index + ':' + encounterOrdinal + ':'
											+ conditionOrdinal));
						}
					}
				}
				connection.commit();
			}
			String query = """
					SELECT ?root ?encounter ?condition
					WHERE {
					  ?root <urn:frontier:type> <urn:frontier:Patient> .
					  OPTIONAL {
					    ?root <urn:frontier:hasEncounter> ?encounter .
					    ?encounter <urn:frontier:hasCondition> ?condition .
					  }
					}
					""";

			try (var connection = repository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(query)
						.explain(Explanation.Level.Optimized);
				LeftJoin optional = findLeftJoin((TupleExpr) explanation.tupleExpr());
				assertNotNull(optional, explanation::toString);
				Join correlatedJoin = findJoin(optional.getRightArg());
				assertNotNull(correlatedJoin, explanation::toString);
				assertNotEquals("hash", correlatedJoin.getStringMetricPlanned("optimizer.joinAlgorithmHint"),
						() -> "A join inside an OPTIONAL with an assured outer binding must preserve the "
								+ "binding for indexed probes instead of independently hashing its global inputs\n"
								+ explanation);
			}
		} finally {
			repository.shutDown();
		}
	}

