	@Test
	void fullQueryAndIsolatedMinusShareLogicalApplicabilityAfterContextualRewrite(@TempDir Path dataDirectory) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(SYNOPSIS_BUDGET_BYTES);
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI q = repository.getValueFactory().createIRI("urn:frontier:applicability-minus-q");
			try (var connection = repository.getConnection()) {
				var values = connection.getValueFactory();
				for (int index = 0; index < 32; index++) {
					var root = values.createIRI("urn:frontier:applicability-minus-root-" + index);
					connection.add(root, PREDICATE,
							values.createIRI("urn:frontier:applicability-minus-object-" + index));
					if ((index & 1) == 0) {
						connection.add(root, q,
								values.createIRI("urn:frontier:applicability-minus-value-" + index));
					}
				}
			}
			assertEquals(FrontierSynopsisStatus.READY, store.rebuildFrontierSynopsis());

			StatementPattern left = new StatementPattern(Var.of("root"), Var.of("p", PREDICATE), Var.of("object"));
			StatementPattern right = new StatementPattern(Var.of("root"), Var.of("q", q), Var.of("value"));
			PackedCostTestSupport.DifferenceCostCall call = PackedCostTestSupport.difference(left, right);
			SailStore sailStore = store.getSailStore();
			try (SailSource branch = sailStore.getExplicitSailSource().fork();
					SailDataset dataset = branch.dataset(store.getDefaultIsolationLevel())) {
				SailDatasetTripleTermSource tripleSource = new SailDatasetTripleTermSource(
						sailStore.getValueFactory(), dataset);
				var statistics = sailStore.getEvaluationStatistics();
				var strategy = store.getEvaluationStrategyFactory()
						.createEvaluationStrategy(null, tripleSource, statistics);
				LmdbEstimatorRuntime runtime = ((LmdbEstimatorRuntimeProvider) statistics).estimatorRuntime();
				LmdbPackedCostModel model = new LmdbPackedCostModel(runtime,
						OptionalLong.of(tripleSource.getSnapshotEpoch().orElseThrow()), true, tripleSource, strategy);
				try (var session = model.openSession(call.query())) {
					PackedCostEstimate leftEstimate = new PackedCostEstimate();
					session.estimateLeaf(call.leftRelationId(), call.emptyContext(), leftEstimate);
					PackedCostEstimate rightEstimate = new PackedCostEstimate();
					session.estimateLeaf(call.rightRelationId(), call.emptyContext(), rightEstimate);
					assertTrue(leftEstimate.evidenceStateId() > 0);
					assertTrue(rightEstimate.evidenceStateId() > 0);

					PackedCostEstimate standalone = new PackedCostEstimate();
					session.refineOperator(call.differenceRelationId(),
							call.standaloneContext(leftEstimate.outputRows(), rightEstimate.outputRows(),
									leftEstimate.evidenceStateId(), rightEstimate.evidenceStateId()),
							standalone);
					PackedCostEstimate exactInputPrefix = new PackedCostEstimate();
					session.refineOperator(call.differenceRelationId(),
							call.exactLeftPrefixContext(leftEstimate.outputRows(), rightEstimate.outputRows(),
									leftEstimate.evidenceStateId(), rightEstimate.evidenceStateId()),
							exactInputPrefix);

					assertEquals(standalone.plannedStringMetric("optimizer.logicalLearningKey"),
							exactInputPrefix.plannedStringMetric("optimizer.logicalLearningKey"),
							"The same canonical Difference must retain one logical key");
					assertEquals(standalone.plannedStringMetric("optimizer.learningApplicability"),
							exactInputPrefix.plannedStringMetric("optimizer.learningApplicability"),
							"Its exact left-input enumeration prefix is topology, not conditional applicability");
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	/*
	 * The q9 contextual-copy shape: under a duplicate-insensitive observer (COUNT DISTINCT) the unused OPTIONAL is
	 * dropped by the rule program, re-interning the MINUS as a second memo group whose scheduled FILTER copies share
	 * one contextual cost identity with the original framing's copies. Fact and learning identities must union the two
	 * groups: a fact minted by one run's framing has to reach the other run's winner (2026-08-05 closure).
	 */
	private static void unusedOptionalGroupDerivationScenario(Path dataDirectory) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(16L * 1024L);
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI q = repository.getValueFactory().createIRI("urn:frontier:derived-minus-q");
			IRI handled = repository.getValueFactory().createIRI("urn:frontier:derived-minus-handled");
			try (var connection = repository.getConnection()) {
				var values = connection.getValueFactory();
				for (int index = 0; index < 128; index++) {
					var root = values.createIRI("urn:frontier:derived-minus-root-" + index);
					connection.add(root, PREDICATE, values.createIRI("urn:frontier:derived-minus-p-" + index));
					if (index < 4) {
						connection.add(root, handled,
								values.createIRI("urn:frontier:derived-minus-practitioner-" + index));
					}
					if ((index & 1) == 0) {
						connection.add(root, q, values.createIRI("urn:frontier:derived-minus-q-" + index));
					}
				}
			}
			assertEquals(FrontierSynopsisStatus.READY, store.rebuildFrontierSynopsis());
			String query = """
					SELECT (COUNT(DISTINCT ?root) AS ?count)
					WHERE {
					  ?root <urn:frontier:p> ?object .
					  OPTIONAL { ?root <urn:frontier:derived-minus-handled> ?practitioner }
					  MINUS { ?root <urn:frontier:derived-minus-q> ?value }
					}
					""";

			TupleExpr observed;
			double rawRows;
			String groupKey;
			LearningApplicability applicability;
			try (var connection = repository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(query)
						.explain(Explanation.Level.Optimized);
				observed = findMinusFraming((TupleExpr) explanation.tupleExpr());
				assertNotNull(observed, explanation::toString);
				groupKey = observed.getStringMetricPlanned("optimizer.frontierLogicalGroupKey");
				assertNotNull(groupKey, explanation::toString);
				LogicalLearningKey logicalGroupKey = LogicalLearningKey.parse(groupKey);
				assertNotNull(logicalGroupKey,
						() -> "Whatever framing wins, its fact key must be versioned and canonical: " + explanation);
				applicability = LearningApplicability.parse(
						observed.getStringMetricPlanned("optimizer.learningApplicability"));
				assertNotNull(applicability, explanation::toString);
				assertEquals("difference", logicalGroupKey.logicalOperator(),
						() -> "Whatever framing wins, its fact key must name the unioned group's canonical"
								+ " member: " + explanation);
				rawRows = observed.getDoubleMetricPlanned("plannedFrontierRows");
				assertTrue(rawRows > 0.0d, explanation::toString);
			}

			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			TupleExpr completed = observed.clone();
			completeLeoOperator(completed, 64L, rawRows, rawRows, 64.0d);
			statistics.estimatorRuntime().feedback().recordOperatorOutcome(completed);
			assertEquals(64.0d, statistics.estimatorRuntime()
					.feedback()
					.exactCardinalityFact(
							LogicalLearningKey.parse(groupKey), applicability),
					0.0d,
					"The completed framing must mint the fact under the unioned group key");

			try (var connection = repository.getConnection()) {
				Explanation explanation = LmdbPlannerAwait.awaitDetachedPlanRefresh(
						() -> connection.prepareTupleQuery(query).explain(Explanation.Level.Optimized));
				TupleExpr pinned = findMinusFraming((TupleExpr) explanation.tupleExpr());
				assertNotNull(pinned, explanation::toString);
				assertEquals(groupKey, pinned.getStringMetricPlanned("optimizer.frontierLogicalGroupKey"),
						() -> "The re-planned framing must key facts by the same unioned group: " + explanation);
				assertEquals(applicability.externalForm(),
						pinned.getStringMetricPlanned("optimizer.learningApplicability"),
						() -> "Equivalent memo-group framings must retain the same fact applicability: " + explanation);
				assertEquals(64.0d, statistics.estimatorRuntime()
						.feedback()
						.exactCardinalityFact(LogicalLearningKey.parse(groupKey), applicability), 0.0d,
						"Planning must not evict the same-stamp fact before the selected alternative consumes it");
				assertEquals("exact-fact",
						pinned.getStringMetricPlanned("optimizer.frontierLeo.output_rows.source"),
						() -> "Run 2's winner must see run 1's measured cardinality regardless of which framing"
								+ " executed: " + explanation);
				var results = QueryResults.asList(connection.prepareTupleQuery(query).evaluate());
				assertEquals(1, results.size());
				assertEquals("64", results.get(0).getValue("count").stringValue());
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void exactFactFloorsCorrelatedNotExistsOuterRowsUnderCrushedEvidence(@TempDir Path dataDirectory) {
		String previousFacts = System.getProperty(
				LmdbFrontierPackedCostSession.FRONTIER_EXACT_CARDINALITY_FACTS_PROPERTY);
		System.setProperty(LmdbFrontierPackedCostSession.FRONTIER_EXACT_CARDINALITY_FACTS_PROPERTY, "true");
		try {
			exactFactFloorScenario(dataDirectory);
		} finally {
			restoreProperty(
					LmdbFrontierPackedCostSession.FRONTIER_EXACT_CARDINALITY_FACTS_PROPERTY, previousFacts);
		}
	}

	private static void exactFactFloorScenario(Path dataDirectory) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(16L * 1024L);
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI q = repository.getValueFactory().createIRI("urn:frontier:floor-minus-q");
			try (var connection = repository.getConnection()) {
				var values = connection.getValueFactory();
				for (int index = 0; index < 200; index++) {
					connection.add(values.createIRI("urn:frontier:floor-minus-first"), PREDICATE,
							values.createIRI("urn:frontier:floor-minus-first-" + index));
					connection.add(values.createIRI("urn:frontier:floor-minus-second"), PREDICATE,
							values.createIRI("urn:frontier:floor-minus-second-" + index));
				}
				connection.add(values.createIRI("urn:frontier:floor-minus-first"), q,
						values.createIRI("urn:frontier:floor-minus-match"));
			}
			assertEquals(FrontierSynopsisStatus.READY, store.rebuildFrontierSynopsis());
			String query = """
					SELECT ?subject ?object
					WHERE {
					  ?subject <urn:frontier:p> ?object .
					  MINUS { ?subject <urn:frontier:floor-minus-q> ?value }
					}
					""";

			StatementPattern observedScan;
			double rawScanRows;
			TupleExpr observedFraming;
			double rawFramingRows;
			try (var connection = repository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(query)
						.explain(Explanation.Level.Optimized);
				observedScan = findPattern((TupleExpr) explanation.tupleExpr(), PREDICATE);
				assertNotNull(observedScan, explanation::toString);
				assertNotEquals("database_exact",
						observedScan.getStringMetricPlanned("plannedFrontierGuarantee"),
						() -> "The fixture needs a learnable (sampled) outer scan: " + explanation);
				rawScanRows = observedScan.getDoubleMetricPlanned("plannedFrontierRows");
				assertTrue(rawScanRows > 100.0d, explanation::toString);
				observedFraming = findMinusFraming((TupleExpr) explanation.tupleExpr());
				assertNotNull(observedFraming, explanation::toString);
				LogicalLearningKey logicalGroupKey = LogicalLearningKey.parse(
						observedFraming.getStringMetricPlanned("optimizer.frontierLogicalGroupKey"));
				assertNotNull(logicalGroupKey, explanation::toString);
				assertEquals("difference", logicalGroupKey.logicalOperator(), explanation::toString);
				rawFramingRows = observedFraming.getDoubleMetricPlanned("plannedFrontierRows");
			}

			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			// One truthful completed run of the whole MINUS mints an exact group fact: 350 rows at this stamp.
			TupleExpr factSource = observedFraming.clone();
			completeLeoOperator(factSource, 350L, rawFramingRows, rawFramingRows, 350.0d);
			statistics.estimatorRuntime().feedback().recordOperatorOutcome(factSource);
			// Cross-query poison: an unrelated workload's feedback then crushes the outer scan's learned estimate
			// (the group fact key is blanked so the lie stays a calibration, not a same-stamp measured fact).
			for (int observation = 0; observation < LEO_CALIBRATION_OBSERVATIONS; observation++) {
				StatementPattern completed = observedScan.clone();
				completed.setStringMetricPlanned("optimizer.frontierLogicalGroupKey", "");
				completed.setStringMetricPlanned("optimizer.costEventDigest", "event-floor-" + observation);
				completed.setStringMetricPlanned("optimizer.frontierStateDigest", "state-floor-" + observation);
				completeLeoOperator(completed, 1L, rawScanRows, rawScanRows, 1.0d);
				statistics.estimatorRuntime().feedback().recordOperatorOutcome(completed);
			}

			try (var connection = repository.getConnection()) {
				Explanation explanation = LmdbPlannerAwait.awaitDetachedPlanRefresh(
						() -> connection.prepareTupleQuery(query).explain(Explanation.Level.Optimized));
				Filter antiJoin = findSemiAntiFilter((TupleExpr) explanation.tupleExpr());
				assertNotNull(antiJoin, explanation::toString);
				double outerRows = antiJoin.getDoubleMetricPlanned("plannedCorrelationOuterRows");
				assertTrue(outerRows >= 300.0d,
						() -> "An exact same-stamp output measurement bounds the probe invocation count from"
								+ " below (output is a subset of the outer input), overruling the crushed learned"
								+ " evidence, but outerRows=" + outerRows + ": " + explanation);
				assertEquals("exact-fact-floor",
						antiJoin.getStringMetricPlanned("plannedCorrelationOuterRowsSource"),
						explanation::toString);
			}

			String previous = System.getProperty(
					LmdbFrontierPackedCostSession.FRONTIER_EXACT_CARDINALITY_FACTS_PROPERTY);
			System.setProperty(
					LmdbFrontierPackedCostSession.FRONTIER_EXACT_CARDINALITY_FACTS_PROPERTY, "false");
			try {
				// Bump the learned revision so the re-planned query cannot reuse the floored plan.
				StatementPattern completed = observedScan.clone();
				completed.setStringMetricPlanned("optimizer.frontierLogicalGroupKey", "");
				completed.setStringMetricPlanned("optimizer.costEventDigest", "event-floor-off");
				completed.setStringMetricPlanned("optimizer.frontierStateDigest", "state-floor-off");
				completeLeoOperator(completed, 1L, rawScanRows, rawScanRows, 1.0d);
				statistics.estimatorRuntime().feedback().recordOperatorOutcome(completed);
				try (var connection = repository.getConnection()) {
					Explanation explanation = LmdbPlannerAwait.awaitDetachedPlanRefresh(
							() -> connection.prepareTupleQuery(query).explain(Explanation.Level.Optimized));
					Filter antiJoin = findSemiAntiFilter((TupleExpr) explanation.tupleExpr());
					assertNotNull(antiJoin, explanation::toString);
					double outerRows = antiJoin.getDoubleMetricPlanned("plannedCorrelationOuterRows");
					assertTrue(outerRows < 300.0d,
							() -> "The kill-switch must restore evidence-only outer rows (pre-fix behavior), but"
									+ " outerRows=" + outerRows + ": " + explanation);
				}
			} finally {
				restoreProperty(
						LmdbFrontierPackedCostSession.FRONTIER_EXACT_CARDINALITY_FACTS_PROPERTY, previous);
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void siblingFamilyFeedbackCannotAlterExactLogicalAlternative(@TempDir Path dataDirectory) throws Exception {
		String previousClamp = System.getProperty(LmdbFrontierPackedCostSession.DEGRADED_CALIBRATION_CLAMP_PROPERTY);
		System.setProperty(LmdbFrontierPackedCostSession.DEGRADED_CALIBRATION_CLAMP_PROPERTY, "true");
		try {
			siblingFamilyIsolationScenario(dataDirectory);
		} finally {
			restoreProperty(LmdbFrontierPackedCostSession.DEGRADED_CALIBRATION_CLAMP_PROPERTY, previousClamp);
		}
	}

	private static void siblingFamilyIsolationScenario(Path dataDirectory) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(16L * 1024L);
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI score = repository.getValueFactory().createIRI("urn:frontier:clamp-score");
			try (var connection = repository.getConnection()) {
				var values = connection.getValueFactory();
				for (int index = 0; index < 512; index++) {
					connection.add(
							values.createIRI("urn:frontier:clamp-subject-" + index),
							score,
							values.createIRI("urn:frontier:clamp-value-" + index));
				}
			}
			assertEquals(FrontierSynopsisStatus.READY, store.rebuildFrontierSynopsis());
			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			String query = """
					SELECT ?subject ?value
					WHERE {
					  ?subject <urn:frontier:clamp-score> ?value .
					  FILTER (STR(?value) = "urn:frontier:clamp-value-1")
					}
					""";

			// An opaque STR() filter over a sampled scan degrades once positive learned mass arrives.
			Filter observed;
			try (var connection = repository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(query)
						.explain(Explanation.Level.Optimized);
				observed = findFilter((TupleExpr) explanation.tupleExpr());
				assertNotNull(observed, explanation::toString);
			}
			statistics.recordFilterOutcome(observed.clone(), 1L, 512L);

			Filter degraded;
			double degradedRows;
			FrontierLearningKey degradedKey;
			LogicalLearningKey degradedLogicalKey;
			try (var connection = repository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(query)
						.explain(Explanation.Level.Optimized);
				degraded = findFilter((TupleExpr) explanation.tupleExpr());
				assertNotNull(degraded, explanation::toString);
				assertEquals("degraded", degraded.getStringMetricPlanned("plannedFrontierStatus"),
						explanation::toString);
				degradedRows = degraded.getResultSizeEstimate();
				assertTrue(degradedRows > 0.0d, explanation::toString);
				degradedKey = FrontierLearningKey.parse(
						degraded.getStringMetricPlanned("optimizer.frontierLearningKey"));
				assertNotNull(degradedKey, explanation::toString);
				degradedLogicalKey = LogicalLearningKey.parse(
						degraded.getStringMetricPlanned("optimizer.logicalLearningKey"));
				assertNotNull(degradedLogicalKey, explanation::toString);
			}

			/*
			 * Pool-only poison: wild observations under a SIBLING key (same family, different binding layout) must
			 * remain diagnostic. D2 permits only the exact canonical logical key and applicability to influence a
			 * winner.
			 */
			FrontierLearningKey sibling = FrontierLearningKey.of(
					degradedKey.operatorFamily(), degradedKey.rawTransform(),
					degradedKey.bindingLayoutFingerprint() + 1L, degradedKey.correlationFingerprint(),
					degradedKey.accessKernel(), degradedKey.indexName(), degradedKey.accessMode());
			LogicalLearningKey siblingLogicalKey = LogicalLearningKey.of(
					degradedLogicalKey.logicalOperator(), degradedLogicalKey.canonicalExpressionDigest() + "-sibling",
					"sibling-child-groups", "sibling-predicate-domain", "v0,v1", "none",
					"bag|duplicate-sensitive|sparql-unbound", "store-defaults|mixed-scope");
			for (int observation = 0; observation < LEO_CALIBRATION_OBSERVATIONS; observation++) {
				Filter poisoned = degraded.clone();
				poisoned.setStringMetricPlanned("optimizer.frontierLearningKey", sibling.externalForm());
				poisoned.setStringMetricPlanned("optimizer.logicalLearningKey", siblingLogicalKey.externalForm());
				poisoned.setStringMetricPlanned("optimizer.frontierLogicalGroupKey", siblingLogicalKey.externalForm());
				poisoned.setStringMetricPlanned("optimizer.costEventDigest", "event-clamp-" + observation);
				poisoned.setStringMetricPlanned("optimizer.frontierStateDigest", "state-clamp-" + observation);
				completeLeoOperator(poisoned, Math.round(degradedRows * 400.0d), degradedRows, 512.0d,
						degradedRows * 400.0d);
				statistics.estimatorRuntime().feedback().recordOperatorOutcome(poisoned);
			}

			try (var connection = repository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(query)
						.explain(Explanation.Level.Optimized);
				Filter isolated = findFilter((TupleExpr) explanation.tupleExpr());
				assertNotNull(isolated, explanation::toString);
				assertEquals(degradedKey,
						FrontierLearningKey.parse(isolated.getStringMetricPlanned("optimizer.frontierLearningKey")),
						explanation::toString);
				assertEquals(degradedRows, isolated.getResultSizeEstimate(), degradedRows * 0.0001d,
						() -> "A sibling family posterior must not alter the exact logical alternative: "
								+ explanation);
			}

			String previous = System.getProperty(LmdbFrontierPackedCostSession.DEGRADED_CALIBRATION_CLAMP_PROPERTY);
			System.setProperty(LmdbFrontierPackedCostSession.DEGRADED_CALIBRATION_CLAMP_PROPERTY, "false");
			try {
				// Bump the learned revision and prove that disabling the old clamp cannot resurrect family pooling.
				Filter poisoned = degraded.clone();
				poisoned.setStringMetricPlanned("optimizer.frontierLearningKey", sibling.externalForm());
				poisoned.setStringMetricPlanned("optimizer.logicalLearningKey", siblingLogicalKey.externalForm());
				poisoned.setStringMetricPlanned("optimizer.frontierLogicalGroupKey", siblingLogicalKey.externalForm());
				poisoned.setStringMetricPlanned("optimizer.costEventDigest", "event-clamp-off");
				poisoned.setStringMetricPlanned("optimizer.frontierStateDigest", "state-clamp-off");
				completeLeoOperator(poisoned, Math.round(degradedRows * 400.0d), degradedRows, 512.0d,
						degradedRows * 400.0d);
				statistics.estimatorRuntime().feedback().recordOperatorOutcome(poisoned);
				try (var connection = repository.getConnection()) {
					Explanation explanation = connection.prepareTupleQuery(query)
							.explain(Explanation.Level.Optimized);
					Filter stillIsolated = findFilter((TupleExpr) explanation.tupleExpr());
					assertNotNull(stillIsolated, explanation::toString);
					assertEquals(degradedRows, stillIsolated.getResultSizeEstimate(), degradedRows * 0.0001d,
							() -> "A safety kill-switch must not restore unsafe family pooling: " + explanation);
				}
			} finally {
				restoreProperty(LmdbFrontierPackedCostSession.DEGRADED_CALIBRATION_CLAMP_PROPERTY, previous);
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void cachedBridgeStagingFitsItsRetainedRowsWithinQueryMemoryBudget(@TempDir Path dataDirectory) {
		long queryMemoryBudget = 64L << 10;
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
				.setFrontierSynopsisBudgetBytes(SYNOPSIS_BUDGET_BYTES)
				.setFrontierQueryMemoryBudgetBytes(queryMemoryBudget)
				.setFrontierRefinementWorkUnits(4_096);
		LmdbStore store = new LmdbStore(dataDirectory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI q = repository.getValueFactory().createIRI("urn:frontier:cached-memory-q");
			IRI subject = repository.getValueFactory().createIRI("urn:frontier:cached-memory-subject");
			try (var connection = repository.getConnection()) {
				var values = connection.getValueFactory();
				for (int index = 0; index < 4; index++) {
					connection.add(subject, PREDICATE,
							values.createIRI("urn:frontier:cached-memory-object-" + index));
				}
				for (int index = 0; index < 160; index++) {
					connection.add(subject, q, values.createIRI("urn:frontier:cached-memory-value-" + index));
				}
			}
			assertEquals(FrontierSynopsisStatus.READY, store.rebuildFrontierSynopsis());
			String query = """
					SELECT ?subject ?object ?value
					WHERE {
					  ?subject <urn:frontier:p> ?object .
					  ?subject <urn:frontier:cached-memory-q> ?value
					}
					""";

			try (var connection = repository.getConnection()) {
				Explanation explanation = connection.prepareTupleQuery(query)
						.explain(Explanation.Level.Optimized);
				StatementPattern completed = findPatterns((TupleExpr) explanation.tupleExpr()).stream()
						.filter(pattern -> pattern.getDoubleMetricPlanned("plannedFrontierFactorCount") == 2.0d)
						.findFirst()
						.orElse(null);
				assertNotNull(completed,
						"retained exact rows fit the hard query-memory budget; staging must not require a full-buffer copy\n"
								+ explanation);
				assertEquals("ready", completed.getStringMetricPlanned("plannedFrontierStatus"),
						explanation::toString);
				assertTrue(completed.getDoubleMetricPlanned("plannedFrontierQueryMemoryPeakBytes") <= queryMemoryBudget,
						explanation::toString);
				assertEquals(640.0d, completed.getDoubleMetricPlanned("plannedFrontierRows"),
						explanation::toString);
				assertEquals(640, QueryResults.asList(connection.prepareTupleQuery(query).evaluate()).size());
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void restoreProperty(String propertyName, String previous) {
		if (previous == null) {
			System.clearProperty(propertyName);
		} else {
			System.setProperty(propertyName, previous);
		}
	}

	private static void completeLeoOperator(TupleExpr operator, long actualRows, double plannedRows,
			double plannedWorkRows, double actualWorkRows) {
		operator.setParentNode(null);
		operator.setCostFeedbackTrackingEnabled(true);
		operator.setCostFeedbackExpectedRows(plannedRows);
		operator.setCostFeedbackExpectedWorkRows(plannedWorkRows);
		operator.setCostFeedbackReportQErrorThreshold(
				LmdbOperatorFeedbackStats.DEFAULT_REPORT_Q_ERROR_THRESHOLD);
		operator.setResultSizeEstimate(plannedRows);
		operator.setCostEstimate(plannedWorkRows);
		operator.setDoubleMetricPlanned(TelemetryMetricNames.PLANNED_WORK_ROWS, plannedWorkRows);
		operator.setCostFeedbackActualRows(actualRows);
		operator.setCostFeedbackActualWorkRows(actualWorkRows);
		operator.setCostFeedbackCloseCountActual(1L);
		operator.setCostFeedbackCompletedActual(true);
		operator.setLongMetricActual(EvaluationStatistics.EXHAUSTED_OPEN_COUNT, 1L);
		operator.setLongMetricActual(TelemetryMetricNames.EXHAUSTED_CLOSE_COUNT_ACTUAL, 1L);
	}

	private static EvaluationStatistics.InvocationAggregateObservation typedCompletedObservation(TupleExpr operator) {
		double plannedRows = operator.getCostFeedbackExpectedRows();
		double actualRows = operator.getCostFeedbackActualRows();
		double plannedWorkRows = operator.getCostFeedbackExpectedWorkRows();
		double actualWorkRows = operator.getCostFeedbackActualWorkRows();
		double plannedSourceRows = operator.getDoubleMetricPlanned("optimizer.costEventSequentialRows");
		double actualSourceRows = operator.getSourceRowsScannedActual();
		plannedSourceRows = Double.isFinite(plannedSourceRows) && plannedSourceRows >= 0.0d
				? plannedSourceRows
				: Double.NaN;
		actualSourceRows = Double.isFinite(actualSourceRows) && actualSourceRows >= 0.0d
				? actualSourceRows
				: Double.NaN;
		EvaluationStatistics.PhysicalWorkVector plannedWork = new EvaluationStatistics.PhysicalWorkVector(
				plannedWorkRows, plannedRows, plannedSourceRows, 0.0d, 1.0d, 0.0d, 0.0d, 0.0d, 0.0d,
				0.0d, 0.0d);
		EvaluationStatistics.PhysicalWorkVector actualWork = new EvaluationStatistics.PhysicalWorkVector(
				actualWorkRows, actualRows, actualSourceRows, 0.0d, 1.0d, 0.0d, 0.0d, 0.0d, 0.0d,
				0.0d, 0.0d);
		return new EvaluationStatistics.InvocationAggregateObservation(
				plannedRows, plannedRows, actualRows, plannedWork, plannedWork, actualWork,
				1L, 1L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L,
				EvaluationStatistics.TerminationClassification.EXHAUSTED, true);
	}

	private static StatementPattern findPattern(TupleExpr expression, IRI predicate) {
		return findPatterns(expression).stream()
				.filter(pattern -> predicate.equals(pattern.getPredicateVar().getValue()))
				.findFirst()
				.orElse(null);
	}

	private static List<StatementPattern> findPatterns(TupleExpr expression) {
		List<StatementPattern> matches = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof StatementPattern pattern) {
					matches.add(pattern);
				}
				node.visitChildren(this);
			}
		});
		return matches;
	}

	private static void assertMappedV2WithoutStatementReplay(TupleExpr expression, Explanation explanation) {
		List<StatementPattern> patterns = findPatterns(expression);
		assertFalse(patterns.isEmpty(), explanation::toString);
		assertTrue(patterns.stream().anyMatch(pattern -> {
			String source = pattern.getStringMetricPlanned(TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE);
			return source != null && source.startsWith("frontier-v2-");
		}), () -> "at least one statement leaf must use the mapped V2 generation\n" + explanation);
		for (StatementPattern pattern : patterns) {
			String source = pattern.getStringMetricPlanned(TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE);
			if (source == null || !source.startsWith("frontier-v2-")) {
				continue;
			}
			assertEquals("ready", pattern.getStringMetricPlanned("plannedFrontierStatus"),
					explanation::toString);
			assertEquals("mapped_statistics", pattern.getStringMetricPlanned("plannedFrontierDisposition"),
					explanation::toString);
			assertNull(pattern.getStringMetricPlanned("plannedFrontierLeafMaterialization"),
					explanation::toString);
			assertTrue(pattern.getDoubleMetricPlanned("plannedFrontierPrimitiveSnapshotProbes") <= 0.0d,
					explanation::toString);
			assertTrue(pattern.getDoubleMetricPlanned("plannedFrontierQueryIndexVisitedRows") <= 0.0d,
					explanation::toString);
		}
		List<TupleExpr> operators = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			protected void meetNode(QueryModelNode node) {
				if (node instanceof TupleExpr tupleExpr) {
					operators.add(tupleExpr);
				}
				node.visitChildren(this);
			}
		});
		for (TupleExpr operator : operators) {
			String source = operator.getStringMetricPlanned(TelemetryMetricNames.PLANNED_ESTIMATE_SOURCE);
			assertFalse("lmdb-finite-connected-surface".equals(source)
					|| "lmdb-finite-alternative-surface".equals(source),
					() -> "a READY V2 plan must not reopen the statement snapshot through " + source + "\n"
							+ explanation);
			assertNull(operator.getStringMetricPlanned("plannedFrontierExactProbeKernel"),
					() -> "a READY V2 plan must not install a legacy exact statement probe\n" + explanation);
		}
	}

